        return False

    # Condition: f(u+v+k) - f(u+k) are all multiples of 4 for k=0, ..., v-1
    for k in range(v):
        n_start = u + k
        n_end = u + v + k

        diff = f(n_end) - f(n_start)
        if diff % 4 != 0:
            return False, k, diff
    return True, None, None

